/* Generated by scripts/build_pwa.py. Cache only this deployment's public app files. */
'use strict';
const CACHE_VERSION = '__VERSION__';
const SHELL_FILES = __SHELL_FILES__;
const CACHE_PREFIX = 'daily-planner:' + self.registration.scope + ':';
const CACHE_NAME = CACHE_PREFIX + CACHE_VERSION;
const shellURLs = new Set(SHELL_FILES.map(file => new URL(file, self.registration.scope).href));
const APP_URL = new URL('mockup.html', self.registration.scope).href;

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE_NAME);
    try {
      await cache.addAll([...shellURLs].map(url => new Request(url, { cache: 'reload' })));
    } catch (error) {
      await caches.delete(CACHE_NAME);
      throw error;
    }
    // Let the browser activate only when older app windows no longer need their worker.
  })());
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(names.filter(name => name.startsWith(CACHE_PREFIX) && name !== CACHE_NAME).map(name => caches.delete(name)));
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', event => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  // Exact allowlist: do not intercept board/AI APIs, uploads, blobs or unrelated pages.
  url.search = '';
  url.hash = '';
  const isAppNavigation = request.mode === 'navigate' && (url.href === APP_URL || url.href === self.registration.scope);
  const key = isAppNavigation ? APP_URL : url.href;
  if (!shellURLs.has(key)) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE_NAME);
    const saved = await cache.match(key);
    if (saved) return saved;
    try {
      const response = await fetch(request);
      if (response.ok && response.type === 'basic' && response.url && new URL(response.url).origin === self.location.origin) await cache.put(key, response.clone());
      return response;
    } catch {
      return new Response('This app file is unavailable offline. Reconnect and reopen the app when you have finished your current work.', { status: 503, headers: { 'Content-Type': 'text/plain; charset=utf-8' } });
    }
  })());
});
